            C#

    using System;
using System.Collections.Generic;

class Program {
    static int minCost(int[] arr) {
        // Create a min-priority queue (element, priority)
        PriorityQueue<int, int> pq = new PriorityQueue<int, int>();

        // Insert all elements into the priority queue
        foreach (int x in arr) {
            pq.Enqueue(x, x);
        }

        // Initialize result
        int res = 0;

        // While size of priority queue is more than 1
        while (pq.Count > 1) {
            // Extract shortest two ropes from pq
            int first = pq.Dequeue();
            int second = pq.Dequeue();

            // Connect the ropes: update result and insert back
            int cost = first + second;
            res += cost;
            pq.Enqueue(cost, cost);
        }

        return res;
    }

    static void Main() {
        int[] arr = { 4, 3, 2, 6 };
        Console.WriteLine(minCost(arr));
    }
}


