    // Min-Heap helper functions
function heapPush(heap, val) {
    heap.push(val);
    let idx = heap.length - 1;
    while (idx > 0) {
        let parent = Math.floor((idx - 1) / 2);
        if (heap[idx] < heap[parent]) {
            [heap[idx], heap[parent]] = [heap[parent], heap[idx]];
            idx = parent;
        } else {
            break;
        }
    }
}

function heapPop(heap) {
    if (heap.length === 0) return null;
    if (heap.length === 1) return heap.pop();

    let top = heap[0];
    heap[0] = heap.pop();
    let idx = 0;
    let n = heap.length;

    while (true) {
        let smallest = idx;
        let left = 2 * idx + 1;
        let right = 2 * idx + 2;

        if (left < n && heap[left] < heap[smallest]) {
            smallest = left;
        }
        if (right < n && heap[right] < heap[smallest]) {
            smallest = right;
        }

        if (smallest !== idx) {
            [heap[idx], heap[smallest]] = [heap[smallest], heap[idx]];
            idx = smallest;
        } else {
            break;
        }
    }

    return top;
}

// Function to find the minimum cost of connecting ropes
function minCost(arr) {
    let heap = [];

    // Insert all elements into the min-heap
    for (let i = 0; i < arr.length; i++) {
        heapPush(heap, arr[i]);
    }

    let res = 0;

    // While size of heap is more than 1
    while (heap.length > 1) {
        // Extract shortest two ropes
        let first = heapPop(heap);
        let second = heapPop(heap);

        // Connect the ropes: update result and insert back
        let sum = first + second;
        res += sum;
        heapPush(heap, sum);
    }

    return res;
}

